+extern "C" bool c_swap_out(natl pid, char *buf)
+{
+	des_proc* p;

+	if (pid > MAX_PROC_ID) {
+		flog(LOG_WARN, "swap_out: pid %u non valido", pid);
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}

+	if (proc_table[pid] == nullptr) {
+		flog(LOG_WARN, "swap_out: processo %u non esiste", pid);
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	p = proc_table[pid];
+
+	if (p == esecuzione) {
+		flog(LOG_WARN, "swap_out: un processo non puo' rimuovere se stesso");
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	if (p->livello == LIV_SISTEMA) {
+		flog(LOG_WARN, "swap_out: non si puo' rimuovere un processo di sistema");
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	if (!p->swapped_out) {
+		if (!c_access((vaddr)buf, DIM_USR_STACK, true)) {
+			flog(LOG_WARN, "swap_out: buffer non valido (Cavallo di Troia)");
+			esecuzione->contesto[I_RAX] = false;
+			return false;
+		}
+
+		paddr pstack = trasforma(p->cr3, fin_utn_p - DIM_USR_STACK);
+		if (pstack) {
+			memcpy(voidptr_cast(buf), voidptr_cast(pstack), DIM_USR_STACK);
+		}
+
+		distruggi_pila(p->cr3, fin_utn_p, DIM_USR_STACK);
+		p->swapped_out = true;
+	}
+
+	esecuzione->contesto[I_RAX] = !p->swapped_out;
+	return !p->swapped_out;
+}
+
+extern "C" bool c_swap_in(natl pid, const char *buf)
+{
+	des_proc* p;
+
+	if (pid > MAX_PROC_ID) {
+		flog(LOG_WARN, "swap_in: pid %u non valido", pid);
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	if (proc_table[pid] == nullptr) {
+		flog(LOG_WARN, "swap_in: processo %u non esiste", pid);
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	p = proc_table[pid];
+
+	if (p->livello == LIV_SISTEMA) {
+		flog(LOG_WARN, "swap_in: non si puo' ricaricare un processo di sistema");
+		esecuzione->contesto[I_RAX] = false;
+		return false;
+	}
+
+	if (p->swapped_out) {
+		if (!c_access((vaddr)buf, DIM_USR_STACK, false)) {
+			flog(LOG_WARN, "swap_in: buffer non valido (Cavallo di Troia)");
+			esecuzione->contesto[I_RAX] = false;
+			return false;
+		}
+
+		if (!crea_pila(p->cr3, fin_utn_p, DIM_USR_STACK, LIV_UTENTE)) {
+			flog(LOG_WARN, "swap_in: creazione pila fallita");
+			esecuzione->contesto[I_RAX] = false;
+			return false;
+		}
+
+		paddr pstack = trasforma(p->cr3, fin_utn_p - DIM_USR_STACK);
+		if (pstack) {
+			memcpy(voidptr_cast(pstack), voidptr_cast(buf), DIM_USR_STACK);
+		}
+
+		p->swapped_out = false;
+
+		if (p->scheduled) {
+			p->scheduled = false;
+			inserimento_lista(pronti, p);
+		}
+	}
+
+	esecuzione->contesto[I_RAX] = true;
+	return true;
+}
+
